from lib import *
L = lambda *a, **k: lesson(17, "A0", *a, **k)
A = "adjective"
L(1, "Мені подобається музика", "Сказати, що вам подобається, і наскільки сильно.",
 "I like… — «мені подобається…». Сильніше: I really like… і I love…. Про речі загалом кажуть без артикля: I like music. I love animals.",
 [W("music", "/ˈmjuːzɪk/", "noun", "музика", "I like music.", "Мені подобається музика."),
  W("film", "/fɪlm/", "noun", "фільм", "It's a good film.", "Це хороший фільм."),
  W("sport", "/spɔːt/", "noun", "спорт", "I like sport.", "Я люблю спорт."),
  W("football", "/ˈfʊtbɔːl/", "noun", "футбол", "He loves football.", "Він обожнює футбол."),
  W("animals", "/ˈænɪmlz/", "noun", "тварини", "I love animals.", "Я обожнюю тварин."),
  W("really", "/ˈriːəli/", "adverb", "справді, дуже", "I really like it.", "Мені це дуже подобається.")],
 [li("Do you have any questions?", "Повторимо. Питань немає. Що відповісти?", ["No, I don't.", "No, I'm not.", "No, I haven't some."], "No, I don't."),
  mt([("music", "музика"), ("film", "фільм"), ("sport", "спорт"), ("football", "футбол"), ("animals", "тварини")], "Те, що люблять майже всі."),
  liu("I really like this film.", "Прослухайте. Що каже людина?", ["Фільм їй дуже подобається", "Фільм їй не подобається", "Вона не бачила фільму"], "Really like — дуже подобається."),
  mc("Як сказати «Я люблю музику»?", ["I like music.", "I like the music.", "I'm like music."], "Про музику загалом — без the."),
  mcu("Що сильніше?", ["I love football.", "I like football.", "I don't like football."], "Love сильніше за like."),
  fb("I ___ like animals. I have three cats!", ["really", "don't", "any"], "Really like — дуже люблю."),
  fb("I don't ___ football. It's boring.", ["like", "likes", "am"], "I don't like."),
  bs("Мені дуже подобається ця музика.", ["I", "really", "like", "this", "music"], ["love", "am"], "I really like this music."),
  tr("Я обожнюю тварин.", ["I love animals"], "I love animals."),
  li("Do you like football?", "Футбол ви не любите. Що відповісти?", ["No, I don't.", "No, I'm not.", "No, I don't like it am."], "No, I don't.")])
L(2, "Я люблю читати", "Сказати, що ви любите робити.",
 "Коли після like стоїть дія, до неї додають -ing: I like reading — «я люблю читати». read → reading, cook → cooking. Якщо слово закінчується на -e, вона зникає: dance → dancing. Іноді приголосна подвоюється: swim → swimming, run → running.",
 [W("reading", "/ˈriːdɪŋ/", "noun", "читання", "I like reading.", "Я люблю читати."),
  W("cooking", "/ˈkʊkɪŋ/", "noun", "готування їжі", "She likes cooking.", "Вона любить готувати."),
  W("swimming", "/ˈswɪmɪŋ/", "noun", "плавання", "I love swimming.", "Я обожнюю плавати."),
  W("dancing", "/ˈdɑːnsɪŋ/", "noun", "танці", "They like dancing.", "Вони люблять танцювати."),
  W("running", "/ˈrʌnɪŋ/", "noun", "біг", "I don't like running.", "Я не люблю бігати."),
  W("travelling", "/ˈtrævəlɪŋ/", "noun", "подорожі", "We love travelling.", "Ми обожнюємо подорожувати.")],
 [fb("I ___ like this film. It's great!", ["really", "don't", "not"], "Really like.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("reading", "читання"), ("cooking", "готування"), ("swimming", "плавання"), ("dancing", "танці"), ("running", "біг")], "Усі закінчуються на -ing."),
  mc("Як сказати «Я люблю читати»?", ["I like reading.", "I like read.", "I like to reading."], "Після like — дія з -ing."),
  mc("Як правильно написати?", ["swimming", "swiming", "swimmeng"], "У swim подвоюється m: swimming."),
  mc("Як правильно написати?", ["dancing", "danceing", "danccing"], "У dance зникає -e: dancing."),
  liu("We love travelling.", "Прослухайте. Що люблять ці люди?", ["Подорожувати", "Танцювати", "Готувати"], "Travelling — подорожі."),
  fb("My husband likes ___. He's a good cook.", ["cooking", "cook", "cooks"], "Likes cooking."),
  bs("Я не люблю бігати.", ["I", "don't", "like", "running"], ["run", "not"], "I don't like running."),
  tr("Я люблю плавати.", ["I like swimming", "I love swimming"], "I like swimming."),
  li("What do you like doing?", "Ви любите читати й готувати. Що відповісти?", ["I like reading and cooking.", "I like read and cook.", "I'm reading and cooking like."], "I like reading and cooking.")])
L(3, "Терпіти не можу чекати", "Сказати, чого ви не любите, і що вам більше до вподоби.",
 "Шкала від найгіршого до найкращого: I hate → I don't like → I don't mind (мені байдуже, не заважає) → I like → I love. I prefer… — «мені більше подобається…»: I prefer tea.",
 [W("hate", "/heɪt/", "verb", "ненавидіти, терпіти не могти", "I hate waiting.", "Терпіти не можу чекати."),
  W("don't mind", "/ˌdəʊnt ˈmaɪnd/", "phrase", "не проти, не заважає", "I don't mind cooking.", "Я не проти готувати."),
  W("prefer", "/prɪˈfɜː/", "verb", "віддавати перевагу", "I prefer tea.", "Мені більше до вподоби чай."),
  W("shopping", "/ˈʃɒpɪŋ/", "noun", "походи по магазинах", "I like shopping.", "Я люблю ходити по магазинах."),
  W("cleaning", "/ˈkliːnɪŋ/", "noun", "прибирання", "I hate cleaning.", "Ненавиджу прибирати."),
  W("waiting", "/ˈweɪtɪŋ/", "noun", "очікування", "I don't like waiting.", "Я не люблю чекати.")],
 [mc("Повторимо. Як сказати «Вона любить танцювати»?", ["She likes dancing.", "She like dance.", "She likes dance."], "She likes dancing."),
  mt([("hate", "ненавидіти"), ("prefer", "віддавати перевагу"), ("don't mind", "не проти"), ("love", "обожнювати")], "Чотири способи висловити ставлення."),
  mt([("shopping", "походи по магазинах"), ("cleaning", "прибирання"), ("waiting", "очікування"), ("cooking", "готування")], "Справи, які люблять не всі."),
  liu("I hate cleaning.", "Прослухайте. Що каже людина?", ["Ненавидить прибирати", "Любить прибирати", "Не проти прибирати"], "Hate — ненавидіти."),
  liu("I don't mind waiting.", "Прослухайте. Що каже людина?", ["Вона не проти почекати", "Вона ненавидить чекати", "Вона не чекатиме"], "I don't mind — не проти."),
  mcu("Що найсильніше з негативних?", ["I hate it.", "I don't like it.", "I don't mind it."], "Hate — найсильніше."),
  fb("Coffee or tea? — I ___ tea.", ["prefer", "hate", "mind"], "I prefer tea — мені більше до вподоби чай."),
  bs("Я не проти готувати.", ["I", "don't", "mind", "cooking"], ["hate", "cook"], "I don't mind cooking."),
  tr("Ненавиджу чекати.", ["I hate waiting"], "I hate waiting."),
  li("Do you like shopping?", "Вам байдуже, не заважає. Що відповісти?", ["I don't mind it.", "I hate mind.", "I'm not mind."], "I don't mind it.")])
L(4, "Яку музику ви любите?", "Розпитати про смаки й уточнити жанр.",
 "What kind of…? — «Який саме…?»: What kind of music do you like? Про іншу людину: Does she like rock? — Yes, she does. З he і she дієслово має -s: He likes comedy.",
 [W("what kind of", "/ˌwɒt ˈkaɪnd əv/", "phrase", "який, якого типу", "What kind of films do you like?", "Які фільми ви любите?"),
  W("rock", "/rɒk/", "noun", "рок", "I like rock.", "Мені подобається рок."),
  W("pop", "/pɒp/", "noun", "поп-музика", "She likes pop.", "Їй подобається поп."),
  W("classical", "/ˈklæsɪkl/", A, "класичний", "Classical music.", "Класична музика."),
  W("comedy", "/ˈkɒmədi/", "noun", "комедія", "I love comedy.", "Я обожнюю комедії."),
  W("horror", "/ˈhɒrə/", "noun", "жахи", "I hate horror films.", "Ненавиджу фільми жахів.")],
 [fb("Tea or coffee? — I ___ coffee.", ["prefer", "mind", "why"], "I prefer coffee.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("rock", "рок"), ("pop", "поп-музика"), ("classical", "класичний"), ("comedy", "комедія"), ("horror", "жахи")], "Жанри музики й кіно."),
  liu("What kind of music do you like?", "Прослухайте. Що вас питають?", ["Яку музику ви любите", "Чи любите ви музику", "Де ви слухаєте музику"], "What kind of — який саме."),
  fb("What kind ___ films do you like?", ["of", "for", "in"], "What kind of."),
  fb("He ___ classical music.", ["likes", "like", "liking"], "З he — likes."),
  fb("___ she like horror films?", ["Does", "Do", "Is"], "З she — Does."),
  liu("She doesn't like pop. She prefers rock.", "Прослухайте. Що їй до вподоби?", ["Рок", "Поп", "Класика"], "She prefers rock."),
  bs("Які фільми ви любите?", ["What", "kind", "of", "films", "do", "you", "like"], ["does"], "What kind of films do you like?"),
  tr("Він любить комедії.", ["He likes comedy", "He likes comedies"], "He likes comedy."),
  li("What kind of music do you like?", "Ви любите рок. Що відповісти?", ["I like rock.", "I'm like rock.", "I like kind of."], "I like rock.")])
L(5, "Я теж", "Погодитися зі співрозмовником і пояснити, чому вам щось подобається.",
 "Me too — «я теж» у відповідь на ствердження: I like pizza. — Me too. Me neither — «я теж ні» у відповідь на заперечення: I don't like horror. — Me neither. Why? — «Чому?». Because… — «Тому що…».",
 [W("me too", "/ˌmiː ˈtuː/", "phrase", "я теж", "I love it. — Me too!", "Обожнюю це. — Я теж!"),
  W("me neither", "/ˌmiː ˈnaɪðə/", "phrase", "я теж ні", "I don't like it. — Me neither.", "Мені це не подобається. — Мені теж."),
  W("why", "/waɪ/", "adverb", "чому", "Why do you like it?", "Чому вам це подобається?"),
  W("because", "/bɪˈkɒz/", "conjunction", "тому що", "Because it's fun.", "Бо це весело."),
  W("fun", "/fʌn/", A, "веселий, цікавий", "Dancing is fun.", "Танцювати весело."),
  W("relaxing", "/rɪˈlæksɪŋ/", A, "розслаблювальний", "Swimming is relaxing.", "Плавання розслабляє.")],
 [li("What kind of films do you like?", "Повторимо. Ви любите комедії. Що відповісти?", ["I like comedy.", "I like kind comedy of.", "I'm comedy."], "I like comedy."),
  mt([("me too", "я теж"), ("me neither", "я теж ні"), ("why", "чому"), ("because", "тому що")], "Слова для живої розмови."),
  mc("Вам кажуть: I love travelling. Ви теж. Що відповісти?", ["Me too!", "Me neither!", "You too!"], "На ствердження — Me too."),
  mc("Вам кажуть: I don't like cleaning. Ви теж ні. Що відповісти?", ["Me neither.", "Me too.", "Me don't."], "На заперечення — Me neither."),
  liu("Why do you like swimming?", "Прослухайте. Що вас питають?", ["Чому ви любите плавати", "Де ви плаваєте", "Чи вмієте ви плавати"], "Why — чому."),
  fb("I like reading ___ it's relaxing.", ["because", "why", "but"], "Because — тому що."),
  fb("Dancing is ___! Let's go!", ["fun", "boring", "because"], "Fun — весело."),
  bs("Бо це весело.", ["Because", "it's", "fun"], ["why", "is"], "Because it's fun."),
  tr("Я теж.", ["Me too"], "Me too."),
  li("Why do you like cooking?", "Вас це розслабляє. Що відповісти?", ["Because it's relaxing.", "Why it's relaxing.", "Because I relaxing am."], "Because it's relaxing.")])
L(6, "Повторення: мої смаки", "Розповісти про свої вподобання й розпитати співрозмовника.",
 "Нових слів немає. Повторюємо: I like і I really like, like + дія з -ing, hate, don't mind і prefer, What kind of…?, Me too і Me neither, because.",
 [],
 [bs("Я люблю читати й подорожувати.", ["I", "like", "reading", "and", "travelling"], ["read", "to"], "I like reading and travelling."),
  fb("She ___ cooking, but she hates cleaning.", ["likes", "like", "is like"], "She likes."),
  li("I hate waiting.", "Ви теж терпіти не можете чекати. Що відповісти?", ["Me too!", "Me neither!", "I don't mind."], "Hate — це ствердження, тому Me too."),
  tr("Яку музику ви любите?", ["What kind of music do you like"], "What kind of music do you like?"),
  liu("I don't like football, but I don't mind tennis.", "Прослухайте. Як людина ставиться до тенісу?", ["Не проти", "Ненавидить", "Обожнює"], "I don't mind — не проти."),
  fb("I like swimming ___ it's relaxing.", ["because", "why", "prefer"], "Because."),
  mc("Як сказати «Він не любить бігати»?", ["He doesn't like running.", "He don't like running.", "He doesn't likes run."], "He doesn't like running."),
  tr("Мені більше до вподоби чай.", ["I prefer tea"], "I prefer tea."),
  liu("Does your wife like horror films? — No, she doesn't. She prefers comedy.", "Прослухайте. Що любить дружина?", ["Комедії", "Фільми жахів", "Рок"], "She prefers comedy."),
  li("I don't like shopping.", "Ви теж не любите. Що відповісти?", ["Me neither.", "Me too.", "Me don't like."], "На заперечення — Me neither.")],
 review=True)
